#!/usr/bin/env Rscript
args<-commandArgs(trailingOnly=TRUE);if(length(args)!=2L)stop("Usage: validate_mv05ay_complete_matrices.R UNITS_DIR OUTPUT_DIR")
units<-normalizePath(args[[1]],mustWork=TRUE);out<-normalizePath(args[[2]],mustWork=FALSE);dir.create(out,recursive=TRUE,showWarnings=FALSE)
setwd("/mnt/e/Repositories/Jonah/PH Pipeline Repo/scPHcompare");pkgload::load_all(".",quiet=TRUE)
scope<-utils::read.csv("docs/audits/mv05ax-complete-scope-2026-08-12.csv",stringsAsFactors=FALSE);manifest<-utils::read.csv("docs/audits/mv04-input-diagram-manifest-2026-08-05.csv",stringsAsFactors=FALSE)
# The accepted manifest hashes the raw serialized diagram. Corrected-landscape
# input manifests deliberately hash the canonical public three-column matrix.
# Recompute that second identity domain from the raw-hash-verified sources.
manifest$raw_diagram_sha256<-manifest$diagram_sha256
manifest$diagram_sha256<-vapply(manifest$result_file,function(path){
  object<-readRDS(path)
  digest::digest(.canonical_public_diagram_v1(object$diagram),
                 algo="sha256",serialize=TRUE)
},character(1))
checks<-list();record<-function(id,pass,evidence){checks[[length(checks)+1]]<<-data.frame(contract_id="mv05ay_validation_v1",validation_id=id,passed=isTRUE(pass),evidence=evidence,stringsAsFactors=FALSE);if(!isTRUE(pass))stop("MV5-AY validation failed: ",id)}
summaries<-resources<-list();pair_count<-0L;dimension_count<-0L;private_ok<-matrix_ok<-input_ok<-resume_ok<-semantic_ok<-combination_ok<-atomic_ok<-logical();matrix_keys<-input_keys<-character()
parse_resource<-function(path){z<-readLines(path,warn=FALSE);elapsed<-sub(".*\\): *","",grep("Elapsed \\(wall clock\\) time",z,value=TRUE));p<-as.numeric(strsplit(elapsed,":",fixed=TRUE)[[1]]);c(wall_seconds=sum(rev(p)*60^(seq_along(p)-1)),max_rss_bytes=as.numeric(sub(".*: *","",grep("Maximum resident set size",z,value=TRUE)))*1024,exit_status=as.numeric(sub(".*: *","",grep("Exit status",z,value=TRUE))))}
prior_resource_path<-file.path(units,"large__sct_whole__gene_topology_v1","process-resource-attempt1.txt");prior_resource<-parse_resource(prior_resource_path)
for(i in seq_len(nrow(scope))){id<-scope$stratum_id[[i]];u<-file.path(units,id);summary<-utils::read.csv(file.path(u,"mv05ay-unit-2026-08-12.csv"),stringsAsFactors=FALSE);summaries[[i]]<-summary;r<-parse_resource(file.path(u,"process-resource.txt"));recovered<-scope$execution_lane[[i]]=="adaptive_concurrent_2";prior_wall<-if(recovered)prior_resource[["wall_seconds"]] else 0;prior_rss<-if(recovered)prior_resource[["max_rss_bytes"]] else 0;cumulative_wall<-r[["wall_seconds"]]+prior_wall;cumulative_rss<-max(r[["max_rss_bytes"]],prior_rss);resources[[i]]<-data.frame(contract_id="mv05ay_resource_v1",stratum_id=id,attempts=if(recovered)2L else 1L,recovery_required=recovered,final_wall_seconds=r[["wall_seconds"]],prior_concurrent_wall_seconds=prior_wall,cumulative_wall_seconds=cumulative_wall,max_rss_bytes=cumulative_rss,exit_status=r[["exit_status"]],within_bounds=cumulative_wall<scope$planned_wall_seconds[[i]]&&cumulative_rss<scope$max_rss_bytes[[i]]&&r[["exit_status"]]==0,stringsAsFactors=FALSE)
 dirs<-list.dirs(file.path(u,"corrected_landscape_v1"),recursive=FALSE,full.names=TRUE);if(length(dirs)!=1L)stop("One sidecar required: ",id);completion<-utils::read.csv(file.path(dirs,"completion-v1.csv"),stringsAsFactors=FALSE);.verify_completion_v1(dirs,completion);value<-readRDS(file.path(dirs,"distance-matrix-v1.rds"));index<-utils::read.csv(file.path(dirs,"pair-index-v1.csv"),stringsAsFactors=FALSE);pair_paths<-file.path(dirs,index$pair_artifact);shards<-lapply(pair_paths,readRDS);pair_count<-pair_count+nrow(index);dimension_count<-dimension_count+2L*nrow(index);private_ok<-c(private_ok,inherits(value,.scph_landscape_matrix_class_v1)&&identical(value$mode,"scientific")&&all(index$h0_certified,index$h1_certified));matrix_ok<-c(matrix_ok,all(vapply(shards,function(x){a<-x$provenance$first_source_id;b<-x$provenance$second_source_id;identical(unname(value$matrices$H0[a,b]),unname(x$distances[["H0"]]))&&identical(unname(value$matrices$H1[a,b]),unname(x$distances[["H1"]]))&&identical(unname(value$matrices$combined[a,b]),unname(x$distances[["combined"]]))},logical(1))));semantic_ok<-c(semantic_ok,all(vapply(shards,function(x){p<-x$provenance;d<-x$dimensions;identical(x$contract_id,"scph_public_landscape_pair_v1")&&identical(x$result_version,1L)&&identical(x$specification,"full_l2_error_controlled_v1")&&identical(x$mode,"scientific")&&identical(p$method_requested,"auto")&&identical(p$exact_max_intervals,500L)&&identical(p$absolute_tolerance,1e-8)&&identical(p$relative_tolerance,1e-8)&&identical(p$level_policy,"all consecutive active levels; zero-pad missing depth")&&identical(p$grid_policy,"none: exact critical breakpoints or adaptive feature partitions")&&identical(p$dimension_policy,"H0 and H1 separate; Euclidean combination secondary")&&identical(p$infinite_interval_policy,"exclude +Inf deaths; report by dimension")&&identical(p$legacy_reproduction,FALSE)&&identical(p$existing_workflow_default_changed,FALSE)&&identical(d$H0$method,"exact_breakpoint_stream_v1")&&identical(d$H0$within_requested_tolerance,TRUE)&&identical(d$H1$within_requested_tolerance,TRUE)&&if(grepl("adaptive",d$H1$method,fixed=TRUE))identical(d$H1$requested_absolute_tolerance,1e-8)&&identical(d$H1$requested_relative_tolerance,1e-8) else identical(d$H1$exact,TRUE)&&identical(d$H1$achieved_absolute_error_estimate,0)},logical(1))));combination_ok<-c(combination_ok,all(vapply(shards,function(x)isTRUE(all.equal(unname(x$distances[["combined"]]),sqrt(unname(x$distances[["H0"]])^2+unname(x$distances[["H1"]])^2),tolerance=.Machine$double.eps^0.5)),logical(1))));atomic_ok<-c(atomic_ok,all(file.exists(pair_paths))&&all(file.info(pair_paths)$size==index$pair_bytes)&&all(vapply(seq_along(pair_paths),function(j)identical(digest::digest(pair_paths[[j]],algo="sha256",file=TRUE),index$pair_sha256[[j]]),logical(1))));input<-utils::read.csv(file.path(dirs,"input-manifest-v1.csv"),stringsAsFactors=FALSE);expected<-manifest[manifest$stratum_id==id,];input_ok<-c(input_ok,nrow(input)==nrow(expected)&&setequal(input$diagram_sha256,expected$diagram_sha256)&&setequal(input$source_id,expected$diagram_id));resume_ok<-c(resume_ok,isTRUE(summary$resumed));matrix_keys<-c(matrix_keys,value$cache_key);input_keys<-c(input_keys,unique(input$input_set_sha256))}
summaries<-do.call(rbind,summaries);resources<-do.call(rbind,resources)
record("scope",nrow(summaries)==8L&&sum(summaries$diagrams)==56L&&pair_count==204L&&dimension_count==408L,"eight strata, 56 diagrams, 204 pairs, 408 dimension results")
record("certificates",all(private_ok)&&all(summaries$all_certified),"all H0/H1 results strictly certified")
record("scientific_contract",all(semantic_ok),"all 204 pairs use all active levels, finite intervals, separate H0/H1, auto/500, strict 1e-8 adaptive control, and legacy-off semantics")
record("descriptive_combination",all(combination_ok),"combined entries are exactly the secondary Euclidean H0/H1 summary")
record("atomic_shards",all(atomic_ok),"all versioned pair shards exist with frozen byte counts and SHA-256 identities")
record("matrix_reconstruction",all(matrix_ok),"every pair shard exactly reconstructs H0, H1, and combined entries")
record("input_identity",all(input_ok),"all eight input manifests reproduce canonical public hashes and source IDs from the 56 raw-hash-verified accepted diagrams")
source_ok<-vapply(seq_len(nrow(manifest)),function(i){object<-readRDS(manifest$result_file[[i]]);identical(digest::digest(manifest$result_file[[i]],algo="sha256",file=TRUE),manifest$result_file_sha256[[i]])&&identical(digest::digest(object$diagram,algo="sha256"),manifest$raw_diagram_sha256[[i]])&&identical(object$provenance$diagram_sha256,manifest$raw_diagram_sha256[[i]])},logical(1))
record("source_immutability",all(source_ok),"all 56 source files and diagrams still match accepted SHA-256 identities")
record("deterministic_identity",length(unique(matrix_keys))==8L&&length(unique(input_keys))==8L&&identical(matrix_keys,summaries$matrix_cache_key)&&identical(input_keys,summaries$input_set_sha256),"eight unique matrix/input identities match returned public sidecars")
record("immutable_resume",all(resume_ok),"all eight completed invocations return verified resume")
record("resources",all(resources$within_bounds),"all processes meet frozen wall/RSS/exit bounds")
recovery_code<-paste(readLines("R/landscape_reference.R",warn=FALSE),collapse="\n");recovery_tests<-paste(readLines("tests/testthat/test-landscape-reference.R",warn=FALSE),collapse="\n")
record("adaptive_recovery",file.exists(prior_resource_path)&&prior_resource[["exit_status"]]==1&&grepl("landscape_reference_integrate_partition",recovery_code,fixed=TRUE)&&grepl("fallback bisects without loosening error budget",recovery_tests,fixed=TRUE),"failed concurrent attempt retained; deterministic strict-budget bisection remediation and tests are present; cumulative resources remain binding")
record("routing",all(summaries$h0_methods=="exact_breakpoint_stream_v1")&&sum(grepl("adaptive",summaries$h1_methods))==2L,"H0 exact throughout; adaptive H1 only in two large gene strata")
record("single_worker_schedule",all(scope$workers==1L)&&sum(scope$execution_lane=="adaptive_concurrent_2")==2L,"one internal worker per process; only two independent adaptive strata scheduled concurrently")
runner_text<-paste(readLines("scripts/run_mv05ay_complete_matrix.R",warn=FALSE),collapse="\n");closed_flags<-c("run_standard_seurat_clustering=FALSE","run_kmeans_clustering=FALSE","run_hierarchical_ph_clustering=FALSE","run_spectral_clustering=FALSE","run_visualizations=FALSE","run_sample_level_heatmap=FALSE","run_cluster=FALSE","run_betti=FALSE","run_cross_iteration=FALSE","metadata_path=NULL")
record("closed_consumption",all(vapply(closed_flags,grepl,logical(1),x=runner_text,fixed=TRUE))&&!grepl("read_corrected_landscape_bundle|corrected_landscape_average_trees|cutree\\(|cluster::pam|outcome|label",runner_text),"runner explicitly disables clustering, visualization, Betti, cross-iteration, metadata, labels, outcomes, and corrected consumers")
record("closed_boundary",is.null(formals(run_postprocessing_pipeline)$corrected_landscape_control),"corrected production remains explicit and default-off")
utils::write.csv(summaries,file.path(out,"mv05ay-production-summary-2026-08-12.csv"),row.names=FALSE,quote=TRUE);utils::write.csv(resources,file.path(out,"mv05ay-resource-summary-2026-08-12.csv"),row.names=FALSE,quote=TRUE);utils::write.csv(do.call(rbind,checks),file.path(out,"mv05ay-independent-validation-2026-08-12.csv"),row.names=FALSE,quote=TRUE)
decision<-data.frame(contract_id="mv05ay_decision_v1",production_accepted=TRUE,partition_authorized=FALSE,stability_prefreeze_authorized=TRUE,next_sprint="MV5-AZ",stringsAsFactors=FALSE);utils::write.csv(decision,file.path(out,"mv05ay-continuation-decision-2026-08-12.csv"),row.names=FALSE,quote=TRUE);cat("MV5-AY validation passed:",length(checks),"categories\n")
